<?php foreach ($products as $item): ?><article class="p-4 rounded-xl bg-surface-container flex flex-wrap items-center gap-4" data-item data-price="<?= (float)$item['price'] ?>">
<div class="flex-1 min-w-48"><strong><?= htmlspecialchars($item['name'], ENT_QUOTES, 'UTF-8') ?></strong><p class="text-sm text-on-surface-variant">SKU <?= htmlspecialchars($item['sku'], ENT_QUOTES, 'UTF-8') ?> · <?= number_format((float)$item['price'], 0, ',', '.') ?> ₫/sp · Còn <?= (int)$item['stock_quantity'] ?></p></div>
<form method="post" class="cart-update flex items-center gap-2"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><button name="delta" value="-1" aria-label="Giảm số lượng" class="px-3 py-2 rounded bg-surface-container-high">−</button><output class="min-w-6 text-center"><?= (int)$item['quantity'] ?></output><button name="delta" value="1" aria-label="Tăng số lượng" class="px-3 py-2 rounded bg-surface-container-high" <?= (int)$item['quantity'] >= (int)$item['stock_quantity'] ? 'disabled' : '' ?>>+</button></form>
<strong><?= number_format((float)$item['price'] * (int)$item['quantity'], 0, ',', '.') ?> ₫</strong>
<form method="post" class="cart-remove"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= (int)$item['id'] ?>"><button class="text-red-300">Xóa</button></form></article><?php endforeach ?>
<form method="post" class="flex gap-2"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="add"><select name="product_id" required class="flex-1 p-3 rounded bg-surface-container"><option value="">Chọn sản phẩm để thêm</option><?php foreach ($catalog as $p): ?><option value="<?= (int)$p['id'] ?>"><?= htmlspecialchars($p['name'], ENT_QUOTES, 'UTF-8') ?> (còn <?= (int)$p['stock_quantity'] ?>)</option><?php endforeach ?></select><button class="px-4 rounded bg-primary text-white">Thêm vào giỏ</button></form></section>
<aside class="p-5 rounded-xl bg-surface-container h-fit"><h2 class="text-xl font-bold mb-4">Thông tin giao hàng</h2><form id="place-order" method="post" class="space-y-3"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="action" value="place">
<?php if (!empty($addresses)): ?><label class="block">Saved address<select id="saved-address" class="block w-full p-3 rounded bg-surface-container-high"><option value="">Enter a new address</option><?php foreach($addresses as $a): ?><option value="<?= htmlspecialchars(json_encode($a,JSON_HEX_APOS|JSON_HEX_QUOT),ENT_QUOTES,'UTF-8') ?>" <?= $a['is_default']?'selected':'' ?>><?= htmlspecialchars($a['label']?:$a['address_line'],ENT_QUOTES,'UTF-8') ?><?= $a['is_default']?' (Default)':'' ?></option><?php endforeach ?></select></label><?php endif ?><label class="block">Name<input required name="shipping_name" maxlength="255" autocomplete="name" class="block w-full p-3 rounded bg-surface-container-high"></label><label class="block">Phone<input required name="shipping_phone" pattern="[0-9+ .()-]{9,20}" autocomplete="tel" class="block w-full p-3 rounded bg-surface-container-high"></label><label class="block">Address<input required name="shipping_address" maxlength="255" autocomplete="street-address" class="block w-full p-3 rounded bg-surface-container-high"></label><div class="grid grid-cols-2 gap-2"><input name="shipping_city" placeholder="Province / City" class="w-full p-3 rounded bg-surface-container-high"><input name="shipping_district" placeholder="District" class="w-full p-3 rounded bg-surface-container-high"><input name="shipping_ward" placeholder="Ward" class="w-full p-3 rounded bg-surface-container-high"></div>
<label class="block">Vận chuyển<select name="shipping_method" id="shipping" required class="block w-full p-3 rounded bg-surface-container-high"><?php foreach($shippingMethods as $m): ?><option value="<?= htmlspecialchars($m['code'],ENT_QUOTES,'UTF-8') ?>" data-fee="<?= (float)$m['fee'] ?>"><?= htmlspecialchars($m['name'],ENT_QUOTES,'UTF-8') ?> · <?= number_format((float)$m['fee'],0,',','.') ?> ₫</option><?php endforeach ?></select></label><label class="block">Thanh toán<select name="payment_method" class="block w-full p-3 rounded bg-surface-container-high"><option value="COD">Thanh toán khi nhận hàng (COD)</option><option value="VNPAY">VNPAY Sandbox</option><option value="MOMO">MoMo Sandbox</option></select></label>
<div class="flex gap-2"><input name="coupon" maxlength="50" placeholder="Mã giảm giá" class="min-w-0 flex-1 p-3 rounded bg-surface-container-high"><button type="button" id="apply-coupon" class="px-3 rounded bg-surface-container-high">Áp dụng</button></div><p id="coupon-note" class="text-sm" aria-live="polite">Mã giảm giá được xác thực khi đặt hàng.</p><p class="flex justify-between">Tạm tính <strong id="subtotal" data-value="<?= (float)$subtotal ?>"><?= number_format((float)$subtotal, 0, ',', '.') ?> ₫</strong></p><p class="flex justify-between">Phí vận chuyển <strong id="shipping-fee">30.000 ₫</strong></p><p class="flex justify-between text-xl">Tổng cộng <strong id="grand-total"><?= number_format((float)$subtotal + (float)($shippingMethods[0]['fee'] ?? 0), 0, ',', '.') ?> ₫</strong></p><button class="w-full p-4 rounded bg-primary text-white font-bold">Đặt hàng</button></form></aside></div><?php endif ?></main>
<script>
(()=>{document.querySelector('#saved-address')?.addEventListener('change',e=>{if(!e.target.value)return;const a=JSON.parse(e.target.value),f=document.querySelector('#place-order');f.elements.shipping_name.value=a.full_name;f.elements.shipping_phone.value=a.phone;f.elements.shipping_address.value=a.address_line;f.elements.shipping_city.value=a.city;f.elements.shipping_district.value=a.district||'';f.elements.shipping_ward.value=a.ward||''});document.querySelector('#saved-address')?.dispatchEvent(new Event('change'));const fmt=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫', sel=document.querySelector('#shipping'), sub=document.querySelector('#subtotal');let discount=0;function total(){if(!sub)return;let fee=Number(sel?.selectedOptions[0]?.dataset.fee||0);document.querySelector('#shipping-fee').textContent=fmt(fee);document.querySelector('#grand-total').textContent=fmt(Math.max(0,Number(sub.dataset.value)-discount)+fee)}function recalc(){if(!sub)return;let value=0;document.querySelectorAll('[data-item]').forEach(row=>{let qty=Number(row.querySelector('output')?.textContent||0);value+=Number(row.dataset.price)*qty;let price=row.querySelector('strong:last-of-type');if(price)price.textContent=fmt(Number(row.dataset.price)*qty)});sub.dataset.value=value;sub.textContent=fmt(value);discount=0;total()}sel?.addEventListener('change',total);total();document.querySelectorAll('.cart-update,.cart-remove').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(form);const btn=e.submitter;if(btn?.name)data.set(btn.name,btn.value);try{const response=await fetch('?page=checkout&ajax=1',{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest'}});const result=await response.json();if(!response.ok)throw Error(result.error||'Không thể cập nhật giỏ hàng');if(data.get('action')==='remove')form.closest('[data-item]').remove();else{const out=form.querySelector('output'),next=Number(out.textContent)+Number(data.get('delta'));if(next<1)form.closest('[data-item]').remove();else out.textContent=next}recalc()}catch(err){alert(err.message)}}));document.querySelector('#apply-coupon')?.addEventListener('click',async()=>{const form=document.querySelector('#place-order'), data=new FormData(form);data.set('action','coupon');try{const r=await fetch('?page=checkout&ajax=1',{method:'POST',body:data,headers:{'X-Requested-With':'XMLHttpRequest'}}),j=await r.json();document.querySelector('#coupon-note').textContent=j.message;if(r.ok){discount=Number(j.discount);total()}}catch{document.querySelector('#coupon-note').textContent='Không kiểm tra được mã.'}})})();
</script></body></html>
